<?php
require_once __DIR__.'/includes/functions.php';
$company=setting('company_name','FitCore Pro');
$tagline=setting('company_tagline','Smart Gym & Fitness Business Platform');
$branches=(int)query_value("SELECT COUNT(*) FROM branches WHERE status='active'");
$activeMembers=(int)query_value("SELECT COUNT(*) FROM members WHERE status='active' AND membership_end>=CURDATE()");
$activeTrainers=(int)query_value("SELECT COUNT(*) FROM trainers WHERE status='active'");
$activeClasses=(int)query_value("SELECT COUNT(*) FROM classes WHERE status='active'");
$retentionDays=rule_int('retention_days',14);$riskThreshold=rule_int('retention_visit_threshold',1);
$atRisk=(int)query_value("SELECT COUNT(*) FROM (SELECT m.id,COUNT(a.id) visits FROM members m LEFT JOIN attendance a ON a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL $retentionDays DAY) WHERE m.status='active' AND m.membership_end>=CURDATE() GROUP BY m.id HAVING visits<=$riskThreshold) x");
$retention=$activeMembers?round((1-$atRisk/$activeMembers)*100,1):100;
?>
