<script>const slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('.slider-dots button')];let i=0;function show(n){slides.forEach((s,x)=>s.classList.toggle('active',x===n));dots.forEach((d,x)=>d.classList.toggle('active',x===n));i=n}dots.forEach((d,x)=>d.onclick=()=>show(x));setInterval(()=>show((i+1)%slides.length),5500);</script></body></html>